### Part 1: The Backend (Node & Express)

This will handle the API logic and store data in memory (for simplicity).

1.  **Create a folder** for the backend:
    ```bash
    mkdir task-app-backend
    cd task-app-backend
    ```

2.  **Initialize the project and install dependencies**:
    ```bash
    npm init -y
    npm install express cors body-parser
    ```

3.  **Create the server file** (`server.js`):
    ```javascript
    const express = require('express');
    const cors = require('cors');
    const bodyParser = require('body-parser');

    const app = express();
    const PORT = 5000;

    // Middleware
    app.use(cors()); // Allow React to talk to this server
    app.use(bodyParser.json());

    // Dummy Data Store (In-memory)
    let tasks = [
        { id: 1, text: "Learn Node.js", completed: false },
        { id: 2, text: "Build a React App", completed: true }
    ];

    // API: Get all tasks
    app.get('/api/tasks', (req, res) => {
        res.json(tasks);
    });

    // API: Add a new task
    app.post('/api/tasks', (req, res) => {
        const newTask = {
            id: tasks.length + 1,
            text: req.body.text,
            completed: false
        };
        tasks.push(newTask);
        res.json(newTask);
    });

    // Start Server
    app.listen(PORT, () => {
        console.log(`Server running on http://localhost:${PORT}`);
    });
    ```

4.  **Run the Backend**:
    ```bash
    node server.js
    ```
    *You should see: "Server running on http://localhost:5000"*

